(()=>{const $=s=>document.querySelector(s);let csrf='',config=null,previewed='',lastText='';const modes=[['intro','宣传页'],['static','静态 dist'],['proxy','后端转发'],['external','现有独立站']];async function api(path,data){const res=await fetch('api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{},body:data?JSON.stringify(data):undefined,credentials:'same-origin'});const type=res.headers.get('content-type')||'';if(!type.includes('application/json'))throw Error('管理服务暂未接入，请检查 Nginx 与管理服务配置');const json=await res.json();if(!res.ok){if(res.status===401&&path!=='session'){csrf='';$('#dashboard').hidden=true;$('#login').hidden=false;}throw Error(json.error||'操作失败')}return json}function read(){return{routes:config.routes.map(r=>({id:r.id,name:r.name,mode:$('#mode-'+r.id).value,port:Number($('#port-'+r.id).value)}))}}function dirty(){previewed='';$('#apply').disabled=true;$('#save-status').textContent='修改后请先预览配置'}function render(){const root=$('#routes');root.replaceChildren();for(const row of config.routes){const box=document.createElement('div');box.className='route';const title=document.createElement('h3');title.textContent=row.name;const url=document.createElement('p');url.textContent='/apps/'+row.id+'/';const fields=document.createElement('div');fields.className='route-fields';const modeLabel=document.createElement('label');modeLabel.textContent='入口方式';const select=document.createElement('select');select.id='mode-'+row.id;for(const [v,label] of modes){if(v==='external'&&row.id!=='qingdeng')continue;if(v==='static'&&!['music','podcast','video','liubao','avatar'].includes(row.id))continue;const option=document.createElement('option');option.value=v;option.textContent=label;select.append(option)}select.value=row.mode;const portLabel=document.createElement('label');portLabel.textContent='本机后端端口';const port=document.createElement('input');port.id='port-'+row.id;port.type='number';port.min='1024';port.max='65535';port.value=row.port;port.disabled=row.mode!=='proxy'&&row.id!=='avatar';select.onchange=()=>{port.disabled=select.value!=='proxy'&&row.id!=='avatar';dirty()};port.oninput=dirty;modeLabel.append(select);portLabel.append(port);fields.append(modeLabel,portLabel);box.append(title,url,fields);root.append(box)}$('#route-count').textContent=' / '+config.routes.length}async function open(){const data=await api('config');config=data.config;lastText=data.nginx;$('#nginx').textContent=lastText;render();$('#login').hidden=true;$('#dashboard').hidden=false}$('#login-form').onsubmit=async e=>{e.preventDefault();$('#login-button').disabled=true;try{const data=await api('session',{password:$('#password').value});csrf=data.csrf;$('#password').value='';await open()}catch(e){$('#login-status').textContent=e.message}finally{$('#login-button').disabled=false}};$('#preview').onclick=async()=>{try{const data=read();const result=await api('preview',data);lastText=result.nginx;$('#nginx').textContent=lastText;previewed=JSON.stringify(data);$('#apply').disabled=false;$('#save-status').textContent='预览已生成；尚未改动服务器'}catch(e){$('#save-status').textContent=e.message}};$('#apply').onclick=async()=>{const data=read();if(JSON.stringify(data)!==previewed){dirty();return}$('#apply').disabled=true;$('#save-status').textContent='正在校验并应用…';try{const result=await api('apply',data);config=result.config;lastText=result.nginx;$('#nginx').textContent=lastText;$('#save-status').textContent=result.message;previewed=''}catch(e){$('#save-status').textContent=e.message}};$('#export').onclick=()=>{if(!lastText)return;const url=URL.createObjectURL(new Blob([lastText],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='aione1-routes.conf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#logout').onclick=async()=>{try{await api('logout',{});location.reload()}catch(e){$('#save-status').textContent=e.message}};api('session').then(async data=>{$('#transport').hidden=data.transportAllowed;$('#login-button').disabled=!data.transportAllowed;if(data.authenticated){csrf=data.csrf;await open()}}).catch(e=>$('#login-status').textContent=e.message)})();